// This code computes the final temperature after the conversion from Fahrenheit to Celsius, rounding to the nearest integer, and then back to Fahrenheit, rounding to the nearest integer again.
       int fahrenheit = 32; // Start with the lower boundary of the range.
       int count = 0; // Counter to keep track of the number of temperatures that equalize.
       while (fahrenheit <= 1000) {
           // Convert Fahrenheit to Celsius, round to the nearest integer.
           double celsius = Math.round((fahrenheit - 32) * 5 / 9);
           // Convert back to Fahrenheit, round to the nearest integer.
           double fahrenheit_new = Math.round(celsius * 9 / 5 + 32);
           // Check if the original and final temperatures are equal.
           if (fahrenheit == fahrenheit_new) {
               count++; // Increment the counter if they are equal.
           }
           fahrenheit++; // Move to the next temperature.
       }
       // Output the count of temperatures that equalize.
       System.out.println("The number of temperatures that equalize is: " + count);
